  'russian_twist': ExerciseGuide(['Сидя, корпус отклонён назад, стопы на полу или чуть приподняты.', 'Поворачивай корпус, касаясь руками пола сбоку.', 'Счёт — касания с обеих сторон вместе.'], 'Двигаются только руки — поворачивай плечи вместе с ними.'),
  'hanging_leg_raise': ExerciseGuide(['Вис на перекладине, плечи активны.', 'Поднимай ноги, подкручивая таз к груди.', 'Опускай медленно, без раскачки.'], 'Махи по инерции — останови раскачку перед каждым повтором.'),
  'jumping_jacks': ExerciseGuide(['Ноги вместе, руки вдоль тела.', 'Прыжком — ноги в стороны, руки над головой.', 'Прыжком обратно. Темп ровный, дыши свободно.'], 'Приземление на пятки — мягко на носки, колени слегка согнуты.'),
  'mountain_climber': ExerciseGuide(['Упор лёжа на прямых руках, плечи над ладонями.', 'По очереди быстро подтягивай колени к груди.', 'Таз не поднимай, корпус прямой.'], 'Таз задран вверх — опусти его в линию с плечами.'),
  'jump_squat': ExerciseGuide(['Присед до параллели, руки перед собой.', 'Мощно выпрыгни вверх.', 'Приземляйся мягко сразу в следующий присед.'], 'Жёсткое приземление на прямые ноги — бережём колени: мягко и с согнутыми коленями.'),
  'burpee': ExerciseGuide(['Присед, ладони на пол.', 'Ноги прыжком назад в упор лёжа, при желании — отжимание.', 'Ноги обратно и прыжок вверх. Тяжело — без прыжка.'], 'Провисает поясница в упоре — держи тело прямым, лучше медленнее.'),
  'pec_deck': ExerciseGuide(['Сиденье — так, чтобы рукояти были на уровне груди, спина прижата.', 'Руки чуть согнуты в локтях, своди их перед грудью по дуге.', 'Пауза на секунду, медленно разводи до лёгкого растяжения груди.'], 'Руки разводятся слишком далеко назад и тянут плечо — останавливайся на линии корпуса.'),
  'cable_fly': ExerciseGuide(['Встань между стойками, шаг вперёд, корпус чуть наклонён.', 'Локти слегка согнуты и не меняют угол всё движение.', 'Своди руки перед собой, словно обнимаешь бочку, и медленно возвращай.'], 'Руки сгибаются и движение превращается в жим — держи угол в локтях постоянным.'),
  'db_fly': ExerciseGuide(['Лёжа на скамье, гантели над грудью, ладони смотрят друг на друга.', 'Локти слегка согнуты, опускай гантели в стороны до уровня корпуса.', 'Своди обратно по той же дуге, напрягая грудь.'], 'Слишком тяжёлые гантели и опускание ниже корпуса — травма плеча. Вес лёгкий, амплитуда умеренная.'),
  'incline_db_press': ExerciseGuide(['Спинка скамьи под 30°, гантели у верха груди.', 'Выжимай вверх и чуть к центру, не стукая гантели.', 'Опускай медленно до уровня груди.'], 'Слишком крутой наклон — работают плечи, а не грудь. Хватит 30°.'),
  'hip_thrust': ExerciseGuide(['Лопатки на краю скамьи, штанга на тазе через мягкую накладку, стопы на ширине плеч.', 'Выталкивай таз вверх пятками до прямой линии от плеч до колен.', 'Сожми ягодицы на секунду вверху, опускайся медленно.'], 'Прогиб в пояснице вверху — подкрути таз и смотри вперёд, а не в потолок.'),
  'hip_abduction': ExerciseGuide(['Сядь глубоко, спина прижата, валики снаружи колен.', 'Разводи колени в стороны до упора.', 'Пауза на секунду и медленно своди, не давая грузу упасть.'], 'Рывок и бросание груза — работает инерция. Темп ровный, вниз медленнее.'),
  'hip_adduction': ExerciseGuide(['Сядь глубоко, валики с внутренней стороны колен, ширину выбери без боли в паху.', 'Своди колени вместе до касания валиков.', 'Медленно разводи обратно до лёгкого растяжения.'], 'Слишком широкая стартовая позиция тянет пах — начинай с узкой и расширяй постепенно.'),
  'cable_kickback': ExerciseGuide(['Манжета на щиколотке, руками держись за стойку, корпус чуть наклонён.', 'Отводи прямую ногу назад и немного вверх за счёт ягодицы.', 'Вернись медленно, не касаясь грузом стопки.'], 'Нога уходит вверх за счёт прогиба в пояснице — двигай только ногой, корпус неподвижен.'),
  'donkey_kick': ExerciseGuide(['Встань на четвереньки: ладони под плечами, колени под тазом.', 'Согнутую ногу поднимай стопой к потолку до линии бедра с корпусом.', 'Сожми ягодицу вверху и опусти без касания пола.'], 'Поясница прогибается вслед за ногой — держи живот подтянутым, поднимай ниже.'),
  'sumo_squat': ExerciseGuide(['Стопы широко, носки развёрнуты наружу, гантель вертикально в опущенных руках.', 'Садись вниз, разводя колени по направлению носков.', 'Вставай через пятки, сжимая ягодицы вверху.'], 'Колени заваливаются внутрь — веди их строго по линии носков.'),
  'step_up': ExerciseGuide(['Тумба или скамья до колена, гантели в опущенных руках.', 'Поставь всю стопу на тумбу и поднимись за счёт этой ноги, не отталкиваясь нижней.', 'Опускайся медленно той же ногой. Повторы — на одну ногу, потом на другую.'], 'Толчок нижней ногой делает работу за верхнюю — нижняя только касается пола.'),
  'reverse_lunge': ExerciseGuide(['Стоя прямо, сделай широкий шаг одной ногой назад.', 'Опустись, пока заднее колено почти не коснётся пола, корпус чуть вперёд.', 'Вернись, толкаясь пяткой передней ноги.'], 'Шаг слишком короткий — колено уходит далеко за носок. Шагай шире.'),
  'lying_leg_curl': ExerciseGuide(['Ляг лицом вниз, валик над пятками, колени чуть за краем скамьи.', 'Сгибай ноги, подтягивая пятки к ягодицам.', 'Медленно разгибай, не выпрямляя до щелчка.'], 'Таз отрывается от скамьи — уменьши вес и прижми бёдра.'),
  'db_shrug': ExerciseGuide(['Стоя, гантели в опущенных прямых руках.', 'Подними плечи прямо вверх к ушам.', 'Задержись на секунду и медленно опусти.'], 'Вращать плечами по кругу — двигай только вверх-вниз.'),
  'barbell_shrug': ExerciseGuide(['Штанга хватом на ширине плеч, руки прямые.', 'Поднимай плечи вверх, не сгибая локти.', 'Пауза наверху, плавно вниз.'], 'Тянуть руками и сгибать локти — работают только трапеции.'),
  'wrist_curl': ExerciseGuide(['Сядь, предплечья на бёдрах ладонями вверх, кисти свисают.', 'Сгибай кисти вверх, поднимая гантели.', 'Опускай медленно на всю амплитуду.'], 'Отрывать предплечья от бёдер — двигаются только кисти.'),
  'reverse_wrist_curl': ExerciseGuide(['Предплечья на бёдрах, ладони вниз.', 'Поднимай тыльную сторону кистей вверх.', 'Медленно опусти.'], 'Большой вес — разгибатели слабые, бери лёгкие гантели.'),
  'reverse_curl': ExerciseGuide(['Штанга хватом сверху на ширине плеч.', 'Сгибай руки, локти прижаты к корпусу.', 'Медленно опускай.'], 'Кисти «ломаются» вниз — держи их на одной линии с предплечьем.'),
  'dead_hang': ExerciseGuide(['Хват сверху на ширине плеч, повисни на прямых руках.', 'Чуть опусти плечи от ушей, корпус не раскачивается.', 'Держи, пока хват не начнёт сдавать.'], 'Плечи висят у ушей — чуть опусти их, так суставу безопаснее.'),
  'front_raise': ExerciseGuide(['Стоя, гантели перед бёдрами.', 'Поднимай прямые руки вперёд до уровня плеч.', 'Медленно опусти, не раскачиваясь.'], 'Закидывать гантели корпусом — возьми легче.'),
  'rotating_db_press': ExerciseGuide(['Сидя, гантели у плеч ладонями к себе.', 'Выжимай вверх, разворачивая ладони вперёд.', 'Опускай с обратным разворотом.'], 'Прогиб в пояснице — прижми спину к спинке скамьи.'),
  'pike_push_up': ExerciseGuide(['Упор лёжа, таз подними вверх — тело уголком.', 'Сгибая локти, опускай макушку к полу перед ладонями.', 'Выжимай себя обратно.'], 'Опускаться грудью, как в обычных отжиманиях, — голова идёт вниз и вперёд.'),
  'cable_lateral_raise': ExerciseGuide(['Встань боком к нижнему блоку, рукоять в дальней руке.', 'Отводи руку в сторону до уровня плеча.', 'Медленно верни.'], 'Поднимать выше плеча и подключать трапецию — до горизонтали достаточно.'),
  'rear_delt_fly': ExerciseGuide(['Наклонись вперёд с прямой спиной, гантели под плечами.', 'Разводи руки в стороны, локти чуть согнуты.', 'Сведи лопатки наверху и медленно опусти.'], 'Раскачивать корпус — он неподвижен, работают задние дельты.'),
  'reverse_pec_deck': ExerciseGuide(['Сядь лицом к тренажёру, рукояти на уровне плеч.', 'Разводи руки назад по дуге.', 'Медленно верни.'], 'Рывки — двигай руками плавно, вес небольшой.'),
  'prone_y_raise': ExerciseGuide(['Ляг на живот, руки вытянуты вперёд буквой «Y», большие пальцы вверх.', 'Подними руки над полом, сводя лопатки.', 'Задержись на 2 секунды и опусти.'], 'Задирать голову — взгляд в пол, шея продолжает спину.'),
  'oblique_crunch': ExerciseGuide(['Лёжа на спине, колени согнуты, руки за головой.', 'Скручивайся, направляя локоть к противоположному колену.', 'Чередуй стороны, опускайся медленно.'], 'Тянуть голову руками — поднимается плечо, шея расслаблена.'),
  'bicycle_crunch': ExerciseGuide(['Лёжа, ноги подняты, руки за головой.', 'Тянись локтем к противоположному колену, другую ногу выпрями.', 'Меняй стороны без рывков.'], 'Махать локтями, не скручиваясь, — поворачивается корпус, а не локоть.'),
  'reverse_crunch': ExerciseGuide(['Лёжа на спине, ноги согнуты и подняты, руки вдоль тела.', 'Подкручивай таз, отрывая его от пола, колени к груди.', 'Медленно опускай таз обратно.'], 'Закидывать ноги рывком — таз поднимает пресс, а не инерция.'),
  'lying_leg_raise': ExerciseGuide(['Лёжа на спине, ладони под ягодицами, ноги прямые.', 'Поднимай ноги до вертикали.', 'Опускай медленно, не касаясь пола.'], 'Поясница отрывается от пола — согни ноги или уменьши амплитуду.'),
  'hollow_hold': ExerciseGuide(['Лёжа на спине, поясница прижата к полу.', 'Подними плечи и прямые ноги над полом, руки вытяни за голову.', 'Держи, дыши ровно.'], 'Поясница отрывается — подними ноги выше или согни их.'),
  'v_up': ExerciseGuide(['Лёжа, руки вытянуты за голову, ноги прямые.', 'Одновременно поднимай руки и ноги, тянись к носкам.', 'Медленно опустись.'], 'Рывок с инерцией — поднимайся силой пресса.'),
  'heel_touch': ExerciseGuide(['Лёжа, колени согнуты, лопатки чуть над полом.', 'Тянись рукой к пятке той же стороны, сгибаясь вбок.', 'Чередуй стороны.'], 'Опускать лопатки на пол между повторами — держи напряжение.'),
  'plank_shoulder_tap': ExerciseGuide(['Упор лёжа на прямых руках, ноги чуть шире плеч.', 'Коснись ладонью противоположного плеча.', 'Чередуй руки, таз неподвижен.'], 'Таз раскачивается — расставь ноги шире.'),
  'db_side_bend': ExerciseGuide(['Стоя, гантель в одной руке.', 'Наклонись в сторону гантели, потом выпрямись.', 'Сделай все повторы и смени сторону.'], 'Наклоняться вперёд — двигайся строго в сторону.'),
  'cable_woodchop': ExerciseGuide(['Встань боком к блоку, рукоять двумя руками сверху.', 'Тяни по диагонали вниз к противоположному бедру, разворачивая корпус.', 'Медленно верни.'], 'Тянуть руками — поворот идёт от корпуса.'),
  'hanging_knee_raise': ExerciseGuide(['Вис на перекладине или упор на локтях в тренажёре.', 'Подтягивай колени к груди, подкручивая таз.', 'Опускай медленно, без раскачки.'], 'Раскачка — останови тело перед следующим повтором.'),
  'ab_wheel': ExerciseGuide(['На коленях, ролик под плечами.', 'Выкатывай ролик вперёд, не прогибая поясницу.', 'Возвращайся силой пресса.'], 'Поясница провисает — уменьши амплитуду.'),
  'knee_plank': ExerciseGuide(['Упор на предплечьях и коленях, локти под плечами.', 'От коленей до макушки — прямая линия.', 'Держи, дыши ровно.'], 'Таз поднят вверх — опусти его в линию с корпусом.'),
  'knee_side_plank': ExerciseGuide(['Лёжа на боку, упор на предплечье и колено, ноги согнуты.', 'Подними таз — тело ровное.', 'Держи и смени сторону.'], 'Таз провисает — подними его в линию с плечами.'),
  'wide_push_up': ExerciseGuide(['Ладони в полтора раза шире плеч.', 'Опускайся грудью к полу, локти в стороны и назад.', 'Выжимай пол, тело прямое.'], 'Локти строго в стороны под 90° — это нагрузка на плечи, держи угол около 60°.'),
  'decline_push_up': ExerciseGuide(['Стопы на стуле или диване, ладони на полу.', 'Опускайся грудью к полу, тело прямое.', 'Выжимай себя вверх.'], 'Провисший таз — напряги пресс и ягодицы.'),
  'negative_push_up': ExerciseGuide(['Упор лёжа, тело прямое.', 'Опускайся к полу за 4–5 секунд.', 'Встань на колени, вернись в упор и повтори.'], 'Падать в конце — контролируй всё опускание.'),
  'db_floor_press': ExerciseGuide(['Лёжа на полу, колени согнуты, гантели над грудью.', 'Опускай, пока плечи не коснутся пола.', 'Выжимай вверх, сводя гантели.'], 'Бросать локти на пол — касайся мягко.'),
  'incline_bench_press': ExerciseGuide(['Скамья под 30°, хват чуть шире плеч.', 'Опускай штангу к верху груди.', 'Выжимай вверх над плечами.'], 'Слишком крутой наклон — работают плечи, а не грудь; 30° достаточно.'),
  'negative_dips': ExerciseGuide(['Запрыгни в упор на брусьях на прямых руках.', 'Опускайся за 4–5 секунд, корпус чуть вперёд.', 'Встань на пол и повтори.'], 'Опускаться ниже, чем позволяют плечи, — до угла 90° в локтях.'),
  'diamond_push_up': ExerciseGuide(['Ладони рядом под грудью.', 'Опускайся, локти идут вдоль корпуса.', 'Выжимай пол.'], 'Локти в стороны — держи их у корпуса.'),
  'overhead_db_extension': ExerciseGuide(['Сидя, гантель двумя руками над головой.', 'Опускай её за голову, локти смотрят вверх.', 'Разгибай руки до прямых.'], 'Локти расходятся — держи их ближе к голове.'),
  'db_kickback': ExerciseGuide(['Наклонись, опершись рукой и коленом о скамью, плечо вдоль корпуса.', 'Разгибай руку назад до прямой.', 'Медленно согни обратно.'], 'Плечо опускается — оно неподвижно, работает только локоть.'),
  'cable_overhead_extension': ExerciseGuide(['Спиной к блоку, канат за головой.', 'Разгибай руки вперёд и вверх.', 'Медленно верни.'], 'Толкать корпусом — двигаются только предплечья.'),
  'close_grip_bench': ExerciseGuide(['Хват на ширине плеч.', 'Опускай штангу к низу груди, локти вдоль корпуса.', 'Выжимай вверх.'], 'Слишком узкий хват ломает кисти — ширины плеч достаточно.'),
  'concentration_curl': ExerciseGuide(['Сидя, локоть упёрт во внутреннюю часть бедра.', 'Сгибай руку к плечу.', 'Медленно опусти до почти прямой.'], 'Помогать корпусом — двигается только предплечье.'),
  'cable_curl': ExerciseGuide(['Лицом к нижнему блоку, прямая рукоять снизу.', 'Сгибай руки, локти прижаты.', 'Опускай медленно.'], 'Локти уходят вперёд — держи их у корпуса.'),
  'preacher_curl': ExerciseGuide(['Плечи лежат на подушке пюпитра, хват снизу.', 'Сгибай руки к плечам.', 'Опускай медленно, не разгибая локти рывком до конца.'], 'Бросать вес вниз — внизу локоть нагружен сильнее всего, опускай под контролем.'),
  'chin_up': ExerciseGuide(['Хват снизу на ширине плеч.', 'Тянись грудью к перекладине, локти вниз.', 'Опускайся до прямых рук.'], 'Подтягиваться рывками с раскачкой — каждое повторение с виса.'),
  'inverted_row': ExerciseGuide(['Ляг под низкую перекладину или край крепкого стола, хват на ширине плеч.', 'Тело прямое, тяни грудь к перекладине.', 'Медленно опустись.'], 'Проверь опору: стол должен стоять мёртво. Таз не провисает — тело как доска.'),
  'scapular_pull_up': ExerciseGuide(['Вис на прямых руках.', 'Не сгибая локтей, опусти плечи и сведи лопатки — тело чуть поднимется.', 'Плавно вернись в вис.'], 'Сгибать руки — работают только лопатки.'),
  'superman': ExerciseGuide(['Лёжа на животе, руки вытянуты вперёд.', 'Одновременно подними руки, грудь и ноги.', 'Задержись на 2 секунды и опустись.'], 'Задирать голову — взгляд в пол.'),
  'db_pullover': ExerciseGuide(['Лёжа на скамье или полу, гантель над грудью двумя руками.', 'Опускай её за голову по дуге, руки чуть согнуты.', 'Возвращай над грудью силой спины.'], 'Сгибать локти сильнее — получается разгибание на трицепс.'),
